package kik.qa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.view.accessibility.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.Callable;import java.util.function.BooleanSupplier;import org.json.*;import kik.i18n.*;

/** Device-only storage and profile-isolation checks. No network or real-title playback. */
public final class RecommendationAudit extends Instrumentation {
 Context c;JSONArray results=new JSONArray();boolean passed=true;String a,b,original,originalList;SharedPreferences profiles;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 Object call(String type,String method,Class<?>[] signature,Object...args)throws Exception{Method m=Class.forName(type).getDeclaredMethod(method,signature);m.setAccessible(true);return m.invoke(null,args);}
 Object make(String type,Class<?>[] signature,Object...args)throws Exception{Constructor<?> k=Class.forName(type).getDeclaredConstructor(signature);k.setAccessible(true);return k.newInstance(args);}
 void check(String name,boolean yes)throws Exception{results.put(new JSONObject().put("name",name).put("passed",yes));Bundle report=new Bundle();report.putString("stream",(yes?"PASS ":"FAIL ")+name+"\n");sendStatus(0,report);if(!yes)throw new AssertionError(name);}
 void choose(String p){profiles.edit().putString("current",p).commit();ProfileStore.completeTasteSetup(c,p);}
 void watch(String link,long position,long watched){Progress.Entry e=new Progress.Entry();e.link=link;e.title="Audit";e.pos=position;e.dur=7_200_000;e.observed=true;e.watchedMs=watched;Progress.save(c,e);}
 Object snapshot(String p)throws Exception{return call("kik.i18n.Recommendations","snapshot",new Class[]{Context.class,String.class},c,p);}
 void rate(String p,String link,int value)throws Exception{check("rating persists for current profile",(Boolean)call("kik.i18n.RatingStore","set",new Class[]{Context.class,String.class,String.class,String.class,String.class,String.class,int.class},c,p,link,"Audit",null,null,value));}
 boolean signal(Object snapshot,String link)throws Exception{for(Object x:(List<?>)get(snapshot,"signals"))if(link.equals(get(x,"link")))return true;return false;}
 String leading(Object snapshot,List<Object> rows)throws Exception{Object row=call("kik.i18n.Recommendations","row",new Class[]{Context.class,Class.forName("kik.i18n.Recommendations$Snapshot"),List.class},c,snapshot,rows);return (String)get(((List<?>)get(row,"items")).get(0),"link");}
 <T>T ui(Callable<T> f){Object[] result=new Object[2];runOnMainSync(()->{try{result[0]=f.call();}catch(Throwable e){result[1]=e;}});if(result[1]!=null)throw new RuntimeException((Throwable)result[1]);return (T)result[0];}
 boolean await(BooleanSupplier f,long timeout){long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){try{if(f.getAsBoolean())return true;}catch(Throwable ignored){}SystemClock.sleep(150);}return false;}
 boolean text(AccessibilityNodeInfo n,String label,boolean click){if(n==null)return false;if(label.equals(String.valueOf(n.getText()))&&(!click||n.isClickable()))return !click||n.performAction(AccessibilityNodeInfo.ACTION_CLICK);for(int i=0;i<n.getChildCount();i++)if(text(n.getChild(i),label,click))return true;return false;}
 boolean clickText(String label){return text(getUiAutomation().getRootInActiveWindow(),label,true);}
 boolean selectFirst(AccessibilityNodeInfo n){if(n==null)return false;if(n.isCheckable()&&n.isEnabled()&&!n.isChecked())return n.performAction(AccessibilityNodeInfo.ACTION_CLICK);for(int i=0;i<n.getChildCount();i++)if(selectFirst(n.getChild(i)))return true;return false;}
 void shot(String name)throws Exception{SystemClock.sleep(550);File dir=new File(c.getExternalFilesDir(null),"design-audit");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
 int rating(String p,String link){try{return (Integer)call("kik.i18n.RatingStore","get",new Class[]{Context.class,String.class,String.class},c,p,link);}catch(Exception e){throw new RuntimeException(e);}}
 void uiChecks()throws Exception{
  String link="https://hdrezka.sh/series/drama/646-vo-vse-tyazhkie-2008.html";Activity film=startActivitySync(new Intent(c,FilmActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("link",link).putExtra("title","Breaking Bad"));
  View chip=(View)get(film,"tasteChip"),down=(View)get(film,"dislikeChip");check("thumbs up is accessible",ui(()->chip.isFocusable()&&"Подобається".contentEquals(chip.getContentDescription())));ui(()->{chip.performClick();return null;});check("thumbs up selects positive rating",await(()->rating(b,link)==1&&ui(()->chip.isSelected()&&!down.isSelected()),5000));
  check("thumbs down is accessible",ui(()->down.isFocusable()&&"Не цікаво".contentEquals(down.getContentDescription())));ui(()->{down.performClick();return null;});check("thumbs down replaces positive rating",await(()->rating(b,link)==-1&&ui(()->down.isSelected()&&!chip.isSelected()),5000));shot("recommendation-feedback");
  ui(()->{down.performClick();return null;});check("repeated thumb click clears rating",await(()->rating(b,link)==0&&ui(()->!chip.isSelected()&&!down.isSelected()),5000));
  ui(()->{film.finish();return null;});for(Progress.Entry entry:Progress.recent(c))Progress.remove(c,entry.link);call("kik.i18n.RatingStore","set",new Class[]{Context.class,String.class,String.class,String.class,String.class,String.class,int.class},c,b,"/films/drama/900000013-dislike.html","Audit",null,null,0);HomeActivity home=(HomeActivity)startActivitySync(new Intent(c,HomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check("personalized home renders",await(()->{try{return (Boolean)get(home,"loadedOnce");}catch(Exception e){return false;}},25000));
  View customize=ui(()->{ViewGroup root=(ViewGroup)home.getWindow().getDecorView();List<View> pending=new ArrayList<View>();pending.add(root);while(!pending.isEmpty()){View v=pending.remove(0);if(v instanceof TextView&&"Налаштувати смак".equals(((TextView)v).getText().toString()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)pending.add(((ViewGroup)v).getChildAt(i));}return null;});check("initial taste control is present",customize!=null);ui(()->{customize.performClick();return null;});check("initial taste screen renders",await(()->text(getUiAutomation().getRootInActiveWindow(),"Оберіть те, що вам подобається",false),5000));shot("recommendation-taste-screen");check("initial favorite can be selected",selectFirst(getUiAutomation().getRootInActiveWindow()));check("initial taste save accessible",clickText("Зберегти"));check("initial selection persists as a positive preference",await(()->{try{for(Object r:(List<?>)call("kik.i18n.RatingStore","list",new Class[]{Context.class,String.class},c,b))if((Integer)get(r,"value")>0)return true;return false;}catch(Exception e){return false;}},10000));ui(()->{home.finish();return null;});
 }
 @Override public void onStart(){c=getTargetContext();profiles=c.getSharedPreferences("kik_profiles",0);original=ProfileStore.current(c);originalList=profiles.getString("list","[]");
  try{
   a=ProfileStore.create(c,"QA Taste A","audit").id;b=ProfileStore.create(c,"QA Taste B","audit").id;
   String drama="/films/drama/900000001-seed.html",comedy="/films/comedy/900000002-seed.html",accidental="/films/drama/900000003-accidental.html",seek="/films/drama/900000004-seek.html";
   choose(a);watch(drama,300_000,300_000);watch(accidental,30_000,5_000);watch(seek,6_000_000,0);Object sa=snapshot(a);
   check("actual watched time creates preference",signal(sa,drama));check("accidental launch is not preference or exclusion",!signal(sa,accidental)&&!((Set<?>)get(sa,"excluded")).contains(accidental));check("seek alone is not preference or exclusion",!signal(sa,seek)&&!((Set<?>)get(sa,"excluded")).contains(seek));
   watch(drama,310_000,10_000);check("watch time accumulates once per saved delta",Progress.get(c,drama).watchedMs==310_000);
   rate(a,"/films/drama/900000005-liked.html",1);Object liked=snapshot(a);check("explicit like enters taste",signal(liked,"/films/drama/900000005-liked.html"));
   choose(b);watch(comedy,300_000,300_000);Object sb=snapshot(b);check("profile B cannot inherit A history",!signal(sb,drama)&&signal(sb,comedy));check("captured A snapshot stays pinned after switching",signal(snapshot(a),drama)&&!signal(snapshot(a),comedy));
   Object group=make("kik.i18n.HomeActivity$Row",new Class[]{String.class},"Audit");List<Object> candidates=(List<Object>)get(group,"items");for(String link:new String[]{"/films/drama/900000011-candidate.html","/films/comedy/900000012-candidate.html"}){Object item=make("kik.i18n.HomeActivity$Item",new Class[]{});set(item,"link",link);set(item,"title","Candidate");candidates.add(item);}List<Object> rows=Arrays.asList(group);
   check("different stored tastes produce different top titles",!leading(sa,rows).equals(leading(sb,rows)));
   boolean rejected=(Boolean)call("kik.i18n.RatingStore","set",new Class[]{Context.class,String.class,String.class,String.class,String.class,String.class,int.class},c,a,comedy,"Audit",null,null,1);check("late rating cannot write into inactive profile",!rejected);
   rate(b,"/films/drama/900000013-dislike.html",-1);Object negative=snapshot(b);check("explicit dislike is excluded",((Set<?>)get(negative,"excluded")).contains("/films/drama/900000013-dislike.html"));
   SharedPreferences cache=c.getSharedPreferences("kik_recommendations_"+a,0);cache.edit().putString("signature",(String)get(sa,"fingerprint")).putString("items","[{\"link\":\"/films/drama/900000021-cached.html\",\"title\":\"Audit\"}]").commit();
   check("recommendation cache stays in its own profile",((List<?>)call("kik.i18n.Recommendations","cached",new Class[]{Context.class,Class.forName("kik.i18n.Recommendations$Snapshot")},c,sa)).size()==1&&((List<?>)call("kik.i18n.Recommendations","cached",new Class[]{Context.class,Class.forName("kik.i18n.Recommendations$Snapshot")},c,sb)).isEmpty());
   choose(a);rate(a,"/films/comedy/900000022-new-like.html",1);check("changed taste invalidates stale candidates",((List<?>)call("kik.i18n.Recommendations","cached",new Class[]{Context.class,Class.forName("kik.i18n.Recommendations$Snapshot")},c,snapshot(a))).isEmpty());
   choose(b);ProfileStore.picked=true;uiChecks();choose(original);ProfileStore.delete(c,a);check("profile deletion removes taste and cache",!new File(c.getFilesDir(),"kik_taste_"+a+".json").exists()&&c.getSharedPreferences("kik_recommendations_"+a,0).getAll().isEmpty());a=null;
  }catch(Throwable e){passed=false;try{results.put(new JSONObject().put("error",e.toString()).put("passed",false));}catch(Exception ignored){}}
  finally{choose(original);if(a!=null)ProfileStore.delete(c,a);if(b!=null)ProfileStore.delete(c,b);profiles.edit().putString("list",originalList).putString("current",original).commit();try{File dir=new File(c.getExternalFilesDir(null),"design-audit");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"recommendations.json"))){out.write(new JSONObject().put("passed",passed).put("checks",results).toString(2).getBytes("UTF-8"));}}catch(Exception e){passed=false;}Bundle result=new Bundle();result.putString("stream","Recommendation storage audit passed="+passed+" checks="+results.length());finish(passed?-1:0,result);}
 }
}
